```suggestion
  // Improved secret detection: check for hardcoded secrets using multiple patterns
  const secretPatterns = [
    /\b(password|pass|pwd|secret|token|api[_-]?key|auth|access[_-]?key)\b\s*[:=]\s*['"][^'"]{4,}['"]/i,
    /\b(password|pass|pwd|secret|token|api[_-]?key|auth|access[_-]?key)\b\s*=\s*`[^`]{4,}`/i,
    /\b(password|pass|pwd|secret|token|api[_-]?key|auth|access[_-]?key)\b\s*:\s*`[^`]{4,}`/i,
    // Object property assignment (e.g., { password: "foo" })
    /['"]?(password|pass|pwd|secret|token|api[_-]?key|auth|access[_-]?key)['"]?\s*:\s*['"][^'"]{4,}['"]/i,
  ];
  for (const pattern of secretPatterns) {
    if (content.match(pattern)) {
      findings.push({
        severity: "critical",
        category: "Security",
