The `analyzeFunctionLengths` function returns an empty array, meaning no long functions will ever be detected regardless of the code being reviewed.
```suggestion
  // Simple regex-based function length analysis for JS/TS
  const results: Array<{ name: string; lines: number; startLine: number }> = [];
  const lines = content.split("\n");
  const functionRegex = /function\s+([a-zA-Z0-9_$]+)?\s*\(([^)]*)\)\s*{|\b([a-zA-Z0-9_$]+)\s*=\s*\(([^)]*)\)\s*=>\s*{/;
  let inFunction = false;
  let funcName = "";
  let funcStart = 0;
  let braceCount = 0;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const match = line.match(functionRegex);
    if (match) {
      inFunction = true;
      funcStart = i;
      funcName = match[1] || match[3] || "<anonymous>";
      braceCount = (line.match(/{/g) || []).length - (line.match(/}/g) || []).length;
      continue;
    }
    if (inFunction) {
      braceCount += (line.match(/{/g) || []).length;
      braceCount -= (line.match(/}/g) || []).length;
      if (braceCount <= 0) {
        // Function ends here
        const funcLines = i - funcStart + 1;
        results.push({ name: funcName, lines: funcLines, startLine: funcStart + 1 });
        inFunction = false;
        funcName = "";
        funcStart = 0;
        braceCount = 0;
      }
    }
  }
  return results;
```

