```

Or using iife:
```typescript
const envServiceKey = iife(() => {
  const fromEnv = Env.get("AICORE_SERVICE_KEY")
  if (fromEnv) return fromEnv
  if (auth?.type === "api") {
    Env.set("AICORE_SERVICE_KEY", auth.key)
    return auth.key
  }
  return undefined
})
```

